{
  "claims": [
    {
      "claim": "The bill would replace every reference to June 30 with June 15 in Tennessee Code Annotated § 49-6-3507(c).",
      "summary_quote": "replace every reference to June 30 with June 15 in Tennessee Code Annotated § 49-6-3507(c)",
      "verdict": "supported",
      "source_quote": "SECTION 1. Tennessee Code Annotated, Section 49-6-3507(c), is amended by\n\ndeleting \"June 30\" wherever it appears and substituting \"June 15\".",
      "error_type": "none",
      "rationale": "The summary accurately states the dates, replacement rule, and subsection to which the amendment applies."
    },
    {
      "claim": "The amended provision relates to education freedom scholarships.",
      "summary_quote": "a provision related to education freedom scholarships",
      "verdict": "supported",
      "source_quote": "AN ACT to amend Tennessee Code Annotated, Title 49,\n relative to education freedom scholarships.",
      "error_type": "none",
      "rationale": "The bill identifies education freedom scholarships as its subject and amends the specified provision."
    },
    {
      "claim": "The bill would take effect upon becoming law.",
      "summary_quote": "It would take effect upon becoming law.",
      "verdict": "supported",
      "source_quote": "SECTION 2. This act takes effect upon becoming a law, the public welfare requiring it.",
      "error_type": "none",
      "rationale": "The summary accurately states the effective-date rule."
    }
  ]
}
